      {
        "layer": "4",
        "name": "Transport",
        "description": "Ensures the transmission of the message reliably and accurately."
      },
      {
        "layer": "5",
        "name": "Sitzung (Session)",
        "description": "Handles starting, stopping, and resuming sessions in communication."
